import{t,getLocale,subscribeLanguage}from './i18n.js';
import{uiLeaf,uiAttribute}from './ui.js';
import{supportPhotoUrl}from './support-photo.js';
import{messageTextMarkup}from './message-emojis.js';
import{mountStaffMessageActions}from './staff-message-actions.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const supportStatuses={open:'supportUi.statusOpen',answered:'supportUi.statusAnswered',closed:'supportUi.statusClosed'};
export function supportInboxDate(value){
 const at=new Date(value);if(!Number.isFinite(at.getTime()))return '';
 const now=new Date(),today=at.getFullYear()===now.getFullYear()&&at.getMonth()===now.getMonth()&&at.getDate()===now.getDate();
 return new Intl.DateTimeFormat(getLocale(),{...(today?{}:{day:'numeric',month:'short',...(at.getFullYear()===now.getFullYear()?{}:{year:'numeric'})}),hour:'2-digit',minute:'2-digit'}).format(at);
}
export function supportInboxMarkup(rows,{owner=false,more=false}={}){
 const initials=name=>String(name).trim().split(/\s+/u).slice(0,2).map(word=>Array.from(word)[0]||'').join('').toLocaleUpperCase(getLocale());
 return '<div class="support-actions support-inbox-toolbar">'+(!owner?'<button type="button" class="button" data-support-new>'+uiLeaf('supportUi.new')+'</button>':'')+'<button type="button" class="button secondary" data-support-refresh>'+uiLeaf('settingsExtra.update')+'</button></div>'+(rows.length?'<div class="support-list support-inbox-list">'+rows.map(row=>{
  const name=owner?(row.nickname||t('supportUi.noNickname')):row.subject,unread=owner?row.owner_unread:row.user_unread,awaiting=owner&&row.awaiting_owner===true,at=row.last_message_at||row.updated_at,preview=row.last_message??(!owner?row.last_reply:null),photo=owner&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(row.user_id||'')?' data-member-avatar="'+esc(row.user_id)+'"':'';
  return '<button type="button" class="support-thread support-inbox-row'+(unread?' is-unread':'')+(awaiting?' is-awaiting':'')+'" data-support-thread="'+esc(row.id)+'"><span class="support-inbox-avatar"'+photo+' aria-hidden="true">'+esc(owner?initials(name):'S')+'</span><span class="support-inbox-copy"><span class="support-inbox-top"><strong dir="auto" title="'+esc(name)+'">'+esc(name)+'</strong><time data-support-date data-support-date-format="inbox" datetime="'+esc(at)+'" title="'+esc(Number.isFinite(Date.parse(at))?new Date(at).toLocaleString(getLocale()):'')+'">'+esc(supportInboxDate(at))+'</time></span>'+(preview||owner?'<span class="support-inbox-preview" dir="auto">'+esc(preview||row.subject)+'</span>':'')+'<span class="support-inbox-bottom">'+(owner&&preview?'<span class="support-inbox-subject" dir="auto" title="'+esc(row.subject)+'">'+esc(row.subject)+'</span>':'')+(supportStatuses[row.status]?'<span class="support-inbox-status" data-state="'+esc(awaiting?'waiting':row.status)+'">'+uiLeaf(awaiting?'supportConversationUi.awaiting':supportStatuses[row.status])+'</span>':'')+(unread?'<span class="support-new-badge'+(!owner?' is-user-reply':'')+'">'+uiLeaf(owner?'supportUi.newBadge':'supportUi.replyBadge')+'</span>':'')+'</span></span></button>';
 }).join('')+'</div>':'<p class="muted support-empty">'+uiLeaf(owner?'supportUi.emptyOwner':'supportUi.emptyUser')+'</p>')+(more?'<button type="button" class="text-button support-inbox-more" data-support-more>'+uiLeaf('supportUi.earlier')+'</button>':'');
}
export function arrangeSupportInbox(root){
 root.classList.add('support-inbox-shell');const toolbar=root.querySelector('.support-inbox-toolbar'),notify=root.querySelector('[data-support-enable-notifications]');
 if(notify){notify.innerHTML=uiLeaf('notifyUi.enableNotifications');notify.setAttribute('aria-label',t('supportUi.notifyReplies'));toolbar.append(notify);}
 if(root.previousElementSibling?.tagName==='H1'){const dot=root.querySelector('.support-state-dot');if(dot)toolbar.append(dot);root.querySelector('.support-heading')?.remove();}
}
export function mountSupportChatView(root,{data,actorId,owner,photoMarkup,onReply,onDelete,onClear,onNotice,isActive=()=>true}={}){
 const panel=root.querySelector('.support-panel'),log=root.querySelector('.support-messages'),doc=root.ownerDocument;
 if(!panel||!log)return null;
 root.classList.add('support-chat-shell','staff-cabinet');panel.classList.add('staff-messenger');log.setAttribute('role','log');log.setAttribute('aria-live','polite');log.setAttribute('aria-relevant','additions text');
 let current=data,disposed=false,signature=null;
 const author=message=>message.owner_reply?t('supportUi.supportReply'):owner?(current.thread.nickname||t('supportUi.user')):t('supportUi.you');
 const message=id=>{const m=current.messages.find(item=>item.id===id);return m?{...m,author_name:author(m)}:null;};
 const actions=mountStaffMessageActions(panel,{actorId,getMessage:message,isActive:()=>!disposed&&isActive(),canReply:()=>current.thread.status!=='closed',getRoom:()=>({id:current.thread.id,title:current.thread.subject,kind:'direct',canClearEveryone:current.canClearEveryone===true}),onReply,onDelete,onClear,onNotice});
 const toolbar=root.querySelector('.support-actions'),button=doc.createElement('button');button.type='button';button.className='text-button support-chat-actions';button.innerHTML='<span aria-hidden="true">⋯</span>';button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-label',t('messageDeletionUi.chatActions'));toolbar?.append(button);button.onclick=()=>actions.openConversation(button);
 function render(next){if(disposed)return;const nextSignature=JSON.stringify({messages:next.messages,photos:(next.photos||[]).map(p=>({message_id:p.message_id,unavailable:!!p.unavailable})),awaiting:next.thread.awaiting_owner===true,waitingSince:next.thread.waiting_since,receiptVisible:next.thread.receipt_visible===true});current=next;if(signature===nextSignature){for(const node of log.querySelectorAll('[data-message]')){const photos=(current.photos||[]).filter(p=>p.message_id===node.dataset.message&&!p.unavailable);[...node.querySelectorAll('.support-photo-item')].forEach((item,index)=>{const url=supportPhotoUrl(photos[index]?.url);if(url){item.querySelector('a').href=url;item.querySelector('[data-support-photo-save]')?.setAttribute('data-support-photo-save',url);}});}return;}signature=nextSignature;actions.close({restore:false});const top=log.scrollTop,bottom=log.scrollHeight-log.clientHeight-top<70;
  log.innerHTML=current.messages.map(m=>{const mine=m.author_id===actorId,q=m.reply,role=m.owner_reply?'supportUi.supportReply':owner?null:'supportUi.you';return '<article class="staff-message support-chat-message'+(mine?' is-mine':'')+'" data-message="'+esc(m.id)+'"><div class="staff-bubble"><div class="staff-message-heading"><strong>'+(role?uiLeaf(role):esc(author(m)))+'</strong><button type="button" class="staff-message-actions" data-message-actions '+uiAttribute('messageDeletionUi.actions',{},'aria-label')+' aria-haspopup="dialog"><span aria-hidden="true">⋯</span></button></div>'+(q?(q.available?'<button type="button" class="staff-message-reply" data-reply-source="'+esc(q.id)+'" '+uiAttribute('messageDeletionUi.openSource',{},'aria-label')+'><strong>'+uiLeaf(q.owner_reply?'supportUi.supportReply':owner?'supportUi.user':'supportUi.you')+'</strong><span>'+esc(q.body)+'</span></button>':'<div class="staff-message-reply">'+uiLeaf('messageDeletionUi.unavailable')+'</div>'):'')+'<p dir="auto">'+messageTextMarkup(m.body)+'</p>'+photoMarkup(current,m.id)+'<time datetime="'+esc(m.created_at)+'" data-support-date data-support-date-format="time">'+esc(new Intl.DateTimeFormat(getLocale(),{hour:'2-digit',minute:'2-digit'}).format(new Date(m.created_at)))+'</time></div></article>';}).join('')+(!owner&&current.thread.awaiting_owner===true&&current.thread.status!=='closed'&&current.thread.receipt_visible===true?'<aside class="support-auto-reply"><strong>'+uiLeaf('supportConversationUi.autoTitle')+'</strong><p>'+uiLeaf('supportConversationUi.autoBody')+'</p></aside>':'');if(bottom)log.scrollTop=log.scrollHeight;else log.scrollTop=top;
 }
 const off=subscribeLanguage(()=>{if(!disposed)button.setAttribute('aria-label',t('messageDeletionUi.chatActions'));});render(data);
 return{render,close:()=>actions.close(),dispose(){if(disposed)return;disposed=true;off();actions.dispose();button.remove();panel.classList.remove('staff-messenger');root.classList.remove('support-chat-shell','staff-cabinet');}};
}
